const crypto = require('crypto');

try {
  const SECRET_KEY = $env["SECRET_KEY"] || 'your-secret-key-here';
  const json = $input.first().json;
  const body = json.body || {};
  const headers = json.headers || {};

  // Extrai refresh_token do body ou cookie
  function getRefreshTokenFromCookie(cookieHeader) {
    if (!cookieHeader) return null;
    const cookies = cookieHeader.split(";").reduce((acc, cookie) => {
      const [name, value] = cookie.trim().split("=");
      acc[name] = value;
      return acc;
    }, {});
    return cookies["refresh_token"] || null;
  }

  const refresh_token = body.refresh_token || getRefreshTokenFromCookie(headers?.cookie);

  // Validação
  if (!refresh_token) {
    return {
      code: 401,
      message: 'Refresh token não fornecido'
    };
  }

  // Simula usuário válido (no fake, qualquer refresh_token é válido)
  const payload = {
    sub: 1,
    iss: 'platform',
    aud: 'platform',
    exp: Math.floor(Date.now() / 1000) + (24 * 60 * 60),
    iat: Math.floor(Date.now() / 1000),
    jti: crypto.randomUUID(),
    name: 'fake-user',
    email: 'fake-user@example.com',
    roles: ['admin']
  };

  function base64urlEscape(str) {
    return str.replace(/\+/g, '-')
      .replace(/\//g, '_')
      .replace(/=/g, '');
  }

  function generateJWT(payload, secret) {
    const header = {
      alg: 'HS256',
      typ: 'JWT'
    };

    const encodedHeader = base64urlEscape(
      Buffer.from(JSON.stringify(header)).toString('base64')
    );
    const encodedPayload = base64urlEscape(
      Buffer.from(JSON.stringify(payload)).toString('base64')
    );

    const signature = base64urlEscape(
      crypto
        .createHmac('sha256', secret)
        .update(encodedHeader + '.' + encodedPayload)
        .digest('base64')
    );

    return encodedHeader + '.' + encodedPayload + '.' + signature;
  }

  function generateRefreshToken() {
    return crypto.randomBytes(32).toString('hex');
  }

  const access_token = generateJWT(payload, SECRET_KEY);
  const new_refresh_token = generateRefreshToken();

  return {
    code: 200,
    data: {
      access_token,
      refresh_token: new_refresh_token,
      token_type: 'bearer',
      payload
    }
  };

} catch (error) {
  return {
    code: 500,
    message: error.message || 'Erro ao renovar token'
  };
}

const { error } = $input.first().json;
return {
  code: 500,
  message: error
};
